import{_ as n,o as e,c as t,a3 as r}from"./chunks/framework.BvvarXmc.js";const k=JSON.parse('{"title":"‍ Manajemen Guru, Staf & Hak Akses","description":"","frontmatter":{},"headers":[],"relativePath":"panduan-admin/data-guru-staf.md","filePath":"panduan-admin/data-guru-staf.md","lastUpdated":null}'),s={name:"panduan-admin/data-guru-staf.md"};function i(l,a,o,u,m,g){return e(),t("div",null,[...a[0]||(a[0]=[r('<h1 id="‍-manajemen-guru-staf-hak-akses" tabindex="-1">‍ Manajemen Guru, Staf &amp; Hak Akses <a class="header-anchor" href="#‍-manajemen-guru-staf-hak-akses" aria-label="Permalink to &quot;‍ Manajemen Guru, Staf &amp; Hak Akses&quot;">​</a></h1><p>Menu ini digunakan untuk mendaftarkan akun pengajar, staf TU, serta mengatur kewenangan (role) masing-masing staf di dalam aplikasi.</p><hr><h2 id="_1-mendaftarkan-guru-baru" tabindex="-1">1. Mendaftarkan Guru Baru <a class="header-anchor" href="#_1-mendaftarkan-guru-baru" aria-label="Permalink to &quot;1. Mendaftarkan Guru Baru&quot;">​</a></h2><ol><li>Masuk ke menu <strong>Kelola</strong> <strong>Data Guru (Teachers)</strong>.</li><li>Klik tombol <strong>+ Tambah Guru</strong>.</li><li>Isi data: <ul><li><strong>NIP / NUPTK</strong> (jika ada).</li><li><strong>Nama Lengkap &amp; Gelar</strong>.</li><li><strong>Email &amp; Nomor Telepon</strong> (email akan menjadi username login).</li><li><strong>Mata Pelajaran yang Diampu</strong>.</li></ul></li><li>Klik <strong>Simpan</strong>. Sistem akan mengirimkan link aktivasi atau membuat kata sandi default untuk guru tersebut.</li></ol><hr><h2 id="_2-menetapkan-wali-kelas-homeroom-teacher" tabindex="-1">2. Menetapkan Wali Kelas (Homeroom Teacher) <a class="header-anchor" href="#_2-menetapkan-wali-kelas-homeroom-teacher" aria-label="Permalink to &quot;2. Menetapkan Wali Kelas (Homeroom Teacher)&quot;">​</a></h2><ol><li>Buka menu <strong>Kelola</strong> <strong>Data Kelas / Rombel</strong>.</li><li>Pilih kelas yang bersangkutan (misal: <em>Kelas XI IPA 2</em>), lalu klik <strong>Edit</strong>.</li><li>Pada kolom <strong>Wali Kelas</strong>, pilih nama guru dari daftar dropdown.</li><li>Klik <strong>Simpan</strong>.</li><li>Guru yang ditunjuk otomatis akan mendapatkan akses ke <strong>Dashboard Wali Kelas</strong> khusus untuk memantau absensi, catatan perilaku, dan pembayaran siswa di kelas binaannya.</li></ol><hr><h2 id="_3-mereset-kata-sandi-password-pengguna" tabindex="-1">3. Mereset Kata Sandi (Password) Pengguna <a class="header-anchor" href="#_3-mereset-kata-sandi-password-pengguna" aria-label="Permalink to &quot;3. Mereset Kata Sandi (Password) Pengguna&quot;">​</a></h2><p>Jika ada siswa, orang tua, atau guru yang lupa kata sandinya:</p><ol><li>Buka menu <strong>Kelola</strong> <strong>Pengguna (Users)</strong>.</li><li>Cari nama atau username pengguna pada kolom pencarian.</li><li>Klik tombol aksi <strong>Titik Tiga (...)</strong> di sebelah kanan nama pilih <strong>Reset Password</strong>.</li><li>Masukkan password sementara yang baru (contoh: <code>Sekolah2026!</code>).</li><li>Beritahukan password baru tersebut kepada pengguna dan minta mereka untuk segera menggantinya setelah login.</li></ol>',12)])])}const p=n(s,[["render",i]]);export{k as __pageData,p as default};
